import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
const F = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'fixtures', 'data.json')
export async function execute(args = {}) {
  const d = JSON.parse(fs.readFileSync(args.input_path || F, 'utf8'))
  const rows = Array.isArray(d) ? d : d.rows
  return { total: rows.reduce((s, r) => s + Number(r.value || 0), 0) }
}
